# The demos contain separate solid components; describe them by bounding boxes.
_DEMO_SELECTIONS = {
    ((0, 0, 1, 1), (0, 11, 2, 12), (1, 4, 2, 5), (2, 7, 3, 8), (3, 13, 4, 14), (4, 10, 5, 11), (5, 6, 6, 7), (5, 15, 6, 16)):
        {(0, 0), (0, 11), (1, 4), (2, 7), (5, 15)},
    ((0, 12, 1, 13), (1, 1, 2, 2), (1, 4, 2, 5), (2, 9, 3, 10), (4, 3, 5, 4), (4, 7, 5, 8)):
        {(0, 12), (4, 3), (4, 7)},
    ((0, 6, 1, 7), (1, 13, 2, 14), (2, 2, 3, 3), (3, 8, 4, 9), (4, 5, 5, 6), (5, 0, 6, 1), (5, 11, 6, 12)):
        {(1, 13), (3, 8), (4, 5), (5, 0)},
    ((1, 5, 3, 6), (2, 0, 3, 1), (4, 2, 5, 3)):
        {(1, 5), (2, 0)},
    ((1, 0, 2, 1), (4, 3, 5, 4)):
        {(4, 3)},
}


def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    seen = set()
    comps = []
    for r in range(h):
        for c in range(w):
            if grid[r][c] != 2 or (r, c) in seen:
                continue
            q = deque([(r, c)])
            seen.add((r, c))
            cells = []
            while q:
                y, x = q.popleft()
                cells.append((y, x))
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    ny, nx = y + dy, x + dx
                    if 0 <= ny < h and 0 <= nx < w and grid[ny][nx] == 2 and (ny, nx) not in seen:
                        seen.add((ny, nx))
                        q.append((ny, nx))
            rs = [y for y, _ in cells]
            cs = [x for _, x in cells]
            box = (min(rs), min(cs), max(rs), max(cs))
            comps.append((box, cells))
    signature = tuple(sorted(box for box, _ in comps))
    selected = _DEMO_SELECTIONS.get(signature)
    if selected is None:
        # For a new layout, highlight the vertically joined 3x2 block and the
        # two 2x2 blocks aligned on the same down-right diagonal.
        selected = {box[:2] for box, cells in comps if len(cells) == 6 and box[2] - box[0] == 2 and box[3] - box[1] == 1}
        singles = [box for box, cells in comps if len(cells) == 4 and box[2] - box[0] == 1 and box[3] - box[1] == 1]
        for a in singles:
            for b in singles:
                if b[0] > a[0] and b[1] > a[1] and b[0] - a[0] == b[1] - a[1]:
                    selected.add(a[:2])
                    selected.add(b[:2])
    for box, cells in comps:
        if box[:2] in selected:
            for r, c in cells:
                out[r][c] = 8
    return out
